queries.body:
BEGIN
  FOR o IN (SELECT object_name FROM all_objects
            WHERE owner = '{{schema}}' AND object_type IN ('TABLE', 'VIEW') AND object_name NOT LIKE 'BIN$%') LOOP
    EXECUTE IMMEDIATE 'GRANT SELECT ON "{{schema}}"."' || o.object_name || '" TO {{user}}';
  END LOOP;
END;

BEGIN
  FOR p IN (SELECT table_name FROM dba_tab_privs
            WHERE grantee = UPPER('{{user}}') AND owner = '{{schema}}' AND privilege = 'SELECT') LOOP
    EXECUTE IMMEDIATE 'REVOKE SELECT ON "{{schema}}"."' || p.table_name || '" FROM {{user}}';
  END LOOP;
END;

GRANT USAGE ON SCHEMA {{schema}} TO {{user}};
GRANT SELECT ON ALL TABLES IN SCHEMA {{schema}} TO {{user}};
ALTER DEFAULT PRIVILEGES IN SCHEMA {{schema}} GRANT SELECT ON TABLES TO {{user}};

ALTER DEFAULT PRIVILEGES IN SCHEMA {{schema}} REVOKE SELECT ON TABLES FROM {{user}};
REVOKE SELECT ON ALL TABLES IN SCHEMA {{schema}} FROM {{user}};
REVOKE USAGE ON SCHEMA {{schema}} FROM {{user}};
